package local.tvmorph.tv;
import android.content.*;import android.security.keystore.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.io.*;import java.util.*;import org.json.*;
final class IptvStore{
 private final Context context;private Xtream client;private final Map<String,JSONArray> cache=new LinkedHashMap<>(),categoryCache=new HashMap<>();private final Map<String,JSONObject> detailCache=new LinkedHashMap<>();private final Map<String,Long> loadedAt=new HashMap<>(),retryAt=new HashMap<>();private final Set<String> refreshing=new HashSet<>();private final java.util.concurrent.ExecutorService updater=java.util.concurrent.Executors.newSingleThreadExecutor();private long cacheAt;private int revision;private final Object catalogLock=new Object();private final CatalogDisk disk;
 private static IptvStore instance;static synchronized IptvStore get(Context c){if(instance==null)instance=new IptvStore(c);return instance;}
 IptvStore(Context c){context=c==null?null:c.getApplicationContext();disk=new CatalogDisk(context,this::key);}
 private javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="tvmorph.iptv";if(!store.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)store.getKey(alias,null);}
 private void save(JSONObject data)throws Exception{saveFile("iptv-account",data);}
 private void saveFile(String name,JSONObject data)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());try(FileOutputStream out=context.openFileOutput(name+".tmp",Context.MODE_PRIVATE)){out.write(cipher.getIV());out.write(cipher.doFinal(data.toString().getBytes("UTF-8")));}try{java.nio.file.Files.move(new File(context.getFilesDir(),name+".tmp").toPath(),new File(context.getFilesDir(),name).toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING,java.nio.file.StandardCopyOption.ATOMIC_MOVE);}catch(java.nio.file.AtomicMoveNotSupportedException e){java.nio.file.Files.move(new File(context.getFilesDir(),name+".tmp").toPath(),new File(context.getFilesDir(),name).toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}}
 private JSONObject readFile(String name)throws Exception{File file=new File(context.getFilesDir(),name);if(!file.exists())throw new IOException("لا يوجد اشتراك خاص محفوظ. أضف بياناته مرة واحدة.");byte[] bytes=new byte[(int)file.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(file))){in.readFully(bytes);}if(bytes.length<28)throw new IOException("Invalid saved IPTV profile");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),"UTF-8"));}
 private Xtream load()throws Exception{if(client!=null)return client;File file=new File(context.getFilesDir(),"iptv-account");if(!file.exists())throw new IOException("أضف اشتراكك من صفحة IPTV على الموبايل الأول.");byte[] bytes=new byte[(int)file.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(file))){in.readFully(bytes);}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));client=new Xtream(new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),"UTF-8")));return client;}
 synchronized void importPhoneProfile(JSONObject payload)throws Exception{try{load();return;}catch(Exception missing){}if(payload==null||payload.optString("server").isEmpty())return;JSONObject clean=new JSONObject(payload.toString());if(clean.optString("profileId").isEmpty())clean.put("profileId",UUID.randomUUID().toString());Xtream next=new Xtream(clean);save(clean);refresh();client=next;}
 synchronized JSONObject connect(JSONObject payload)throws Exception{if(payload.optBoolean("restorePersonal",false))payload=readFile("iptv-personal");payload=payload.optString("type").equals("m3u")?M3uPlaylist.normalize(payload):XtreamCredentials.normalize(payload);Xtream next=new Xtream(payload);JSONObject result=next.auth();String profile=payload.optString("profileId",UUID.randomUUID().toString());Xtream previous=null;try{previous=load();}catch(Exception ignored){}if(previous!=null){if(!previous.config.optBoolean("publicMode",false))saveFile("iptv-personal",previous.config);if(previous.server.equals(next.server)&&previous.user.equals(next.user))profile=previous.config.optString("profileId",profile);}if(!payload.optBoolean("publicMode",false))try{JSONObject saved=readFile("iptv-personal");if(saved.optString("server").equals(next.server)&&saved.optString("username").equals(next.user))profile=saved.optString("profileId",profile);}catch(Exception ignored){}payload.put("profileId",profile);next.config.put("profileId",profile);if(!payload.optBoolean("publicMode",false))saveFile("iptv-personal",payload);save(payload);refresh();client=next;result.put("type",payload.optString("type","xtream")).put("publicMode",payload.optBoolean("publicMode",false)).put("profileId",profile).put("hasPersonal",new File(context.getFilesDir(),"iptv-personal").exists());return result;}
 synchronized JSONObject summary()throws Exception{Xtream c=load();return new JSONObject().put("configured",true).put("type",c.config.optString("type","xtream")).put("publicMode",c.config.optBoolean("publicMode",false)).put("hasPersonal",!c.config.optBoolean("publicMode",false)||new File(context.getFilesDir(),"iptv-personal").exists()).put("viewerName",UiSettings.prefs(context).getString("viewerName","Family")).put("viewerId",UiSettings.prefs(context).getString("viewerId","default")).put("profileId",c.config.optString("profileId","default")).put("name",c.config.optString("name","My TV")).put("live",c.config.optBoolean("live",true)).put("vod",c.config.optBoolean("vod",true)).put("series",c.config.optBoolean("series",true));}
 private void check(Xtream c,int version)throws IOException{if(client!=c||revision!=version)throw new IOException("المكتبة اتغيرت. جرّب فتح القسم تاني.");}
 private void expire(){if(System.currentTimeMillis()-cacheAt>300000L){detailCache.clear();cacheAt=System.currentTimeMillis();}}
 JSONObject list(JSONObject payload)throws Exception{
  String kind=payload.optString("kind","live"),category=payload.optString("category",""),search=payload.optString("search","").toLowerCase(Locale.ROOT),key=kind+":"+category;Xtream c;int version;JSONArray all;String epoch;
  if(!search.isEmpty()&&!kind.equals("episode")){category="";key=kind+":";}
  synchronized(this){c=load();version=revision;expire();all=cache.get(key);epoch=disk.epoch();}
  if(!Arrays.asList("live","vod","series","episode").contains(kind))throw new IOException("Invalid content type");if(!kind.equals("episode")&&!c.config.optBoolean(kind,true))throw new IOException("القسم ده غير مفعّل في إعدادات الاشتراك.");
  if(all==null)synchronized(catalogLock){synchronized(this){check(c,version);all=cache.get(key);}if(all==null){all=disk.read(c.config.optString("profileId"),epoch,key);long at=disk.savedAt(c.config.optString("profileId"),epoch,key);if(all==null){all=kind.equals("episode")?c.episodes(category):c.list(kind,category);at=System.currentTimeMillis();disk.save(c.config.optString("profileId"),epoch,key,all);}synchronized(this){check(c,version);rememberCatalog(key,all,at);}}}
  updateLater(c,version,epoch,key,kind,category,false);
  if(payload.optString("order").equals("recent")){java.util.List<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<all.length();i++)sorted.add(all.getJSONObject(i));java.util.Collections.sort(sorted,(a,b)->Long.compare(b.optLong("added",0),a.optLong("added",0)));all=new JSONArray(sorted);}
  int page=Math.max(0,payload.optInt("page",0)),start=page*60,total=0;JSONArray items=new JSONArray();
  if(search.isEmpty()){total=all.length();for(int i=start;i<Math.min(total,start+60);i++)items.put(decorate(all.getJSONObject(i),c));}
  else for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(item.optString("name").toLowerCase(Locale.ROOT).contains(search)){if(total>=start&&items.length()<60)items.put(decorate(item,c));total++;}}
  synchronized(this){check(c,version);}return new JSONObject().put("items",items).put("total",total).put("page",page).put("hasMore",(page+1)*60<total);
 }

 private void rememberCatalog(String key,JSONArray rows,long at){cache.remove(key);cache.put(key,rows);loadedAt.put(key,at);long size=0;for(JSONArray value:cache.values())size+=value.length()*1024L;while(cache.size()>1&&(cache.size()>6||size>24*1024*1024L)){String oldest=cache.keySet().iterator().next();size-=cache.remove(oldest).length()*1024L;loadedAt.remove(oldest);}}
 private void updateLater(Xtream c,int version,String epoch,String key,String kind,String category,boolean categories){
  final String taskKey=version+":"+key;synchronized(this){long now=System.currentTimeMillis();if(client!=c||revision!=version||now-loadedAt.getOrDefault(key,0L)<CatalogDisk.FRESH||now-retryAt.getOrDefault(key,0L)<60000||!refreshing.add(taskKey))return;retryAt.put(key,now);}
  updater.execute(()->{try{JSONArray rows=categories?c.categories(kind):kind.equals("episode")?c.episodes(category):c.list(kind,category);synchronized(this){check(c,version);if(categories){categoryCache.put(kind,rows);loadedAt.put(key,System.currentTimeMillis());}else rememberCatalog(key,rows,System.currentTimeMillis());disk.save(c.config.optString("profileId"),epoch,key,rows);}}catch(Exception ignored){}finally{synchronized(this){refreshing.remove(taskKey);}}});
 }
 private JSONObject decorate(JSONObject source,Xtream c)throws Exception{JSONObject item=new JSONObject(source.toString());int position=0;if(UiSettings.prefs(context).getBoolean("resume",true)&&Arrays.asList("vod","episode").contains(item.optString("kind")))position=PlaybackMemory.get(context,PlaybackMemory.key(PlaybackMemory.account(context,c.config.optString("profileId","default")),item.optString("kind"),item.optString("id")));item.put("resumeMs",position);return item;}
 synchronized JSONObject history()throws Exception{return progress(PlaybackHistory.entries(context,load().config.optString("profileId","default")));}
 synchronized JSONObject progress(JSONArray items)throws Exception{Xtream c=load();JSONArray output=new JSONArray();if(items!=null)for(int i=0;i<Math.min(200,items.length());i++){JSONObject item=items.optJSONObject(i);if(item!=null)output.put(decorate(item,c));}return new JSONObject().put("items",output);}
 synchronized void refresh(){revision++;if(client!=null)client.clearMetadata();cache.clear();categoryCache.clear();detailCache.clear();loadedAt.clear();retryAt.clear();refreshing.clear();cacheAt=System.currentTimeMillis();disk.reset();}
 JSONObject categories(String kind)throws Exception{if(!Arrays.asList("live","vod","series").contains(kind))throw new IOException("Invalid category type");Xtream c;int version;JSONArray rows;synchronized(this){c=load();version=revision;expire();rows=categoryCache.get(kind);}String epoch=disk.epoch(),key="categories:"+kind;if(rows==null)synchronized(catalogLock){synchronized(this){check(c,version);rows=categoryCache.get(kind);}if(rows==null){rows=disk.read(c.config.optString("profileId"),epoch,key);long at=disk.savedAt(c.config.optString("profileId"),epoch,key);if(rows==null){rows=c.categories(kind);at=System.currentTimeMillis();disk.save(c.config.optString("profileId"),epoch,key,rows);}synchronized(this){check(c,version);categoryCache.put(kind,rows);loadedAt.put(key,at);}}}updateLater(c,version,epoch,key,kind,"",true);return new JSONObject().put("items",rows);}
 JSONObject details(JSONObject item)throws Exception{Xtream c;int version;JSONObject value;String key=item.optString("kind")+":"+item.optString("id");synchronized(this){c=load();version=revision;expire();value=detailCache.get(key);}if(value==null){value=c.details(item);synchronized(this){check(c,version);detailCache.put(key,value);while(detailCache.size()>30)detailCache.remove(detailCache.keySet().iterator().next());}}synchronized(this){check(c,version);}return decorate(value,c);}
 JSONObject epg(String id)throws Exception{Xtream c;int version;synchronized(this){c=load();version=revision;}JSONObject result=c.epg(id);synchronized(this){check(c,version);}return result;}
 synchronized String playback(JSONObject item)throws Exception{return load().stream(item);}
 synchronized void clear(){if(context!=null){context.deleteFile("iptv-account");context.deleteFile("iptv-personal");}client=null;refresh();}
}

